const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='trainer-study-v1';const fresh=()=>({version:1,history:[],wrong:{},stars:[],learned:[],days:[],notes:{},caseAnswers:{},caseChecks:{},exams:[],activeExam:null,date:'',plan:[]});let state;
try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{state=fresh()}
let page='home',session=null,pos=0,selection=[],revealed=false,result=null,cardIndex=0,flipped=false,filterModule='all',filterType='all',filterText='';
const navs=[['home','⌂','学习总览'],['practice','▤','题目练习'],['wrong','↺','错题复习'],['cards','◇','要点速记'],['exam','◷','模拟考试'],['cases','▧','实操训练'],['guide','☷','备考指南']];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('浏览器保存失败，请立即导出备份')}}
function today(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function activity(){if(!state.days.includes(today()))state.days.push(today())}
const pct=(a,b)=>b?Math.round(a/b*100):0;const eq=(a,b)=>a.length===b.length&&[...a].sort().join(',')===[...b].sort().join(',');const qby=id=>questions.find(q=>q.id===id);
function shuffled(arr){return [...arr].sort(()=>Math.random()-.5)}
function go(p){location.hash=p;if(page===p)render()}
function heading(title,sub){return `<div class="eyebrow">AI TRAINER STUDY ROOM</div><h1>${title}</h1><p class="muted">${sub}</p>`}
function render(){page=location.hash.slice(1)||'home';if(!navs.some(x=>x[0]===page))page='home';$('#nav').innerHTML=navs.map(n=>`<a class="${page===n[0]?'active':''}" href="#${n[0]}"><span>${n[1]}</span>${n[2]}</a>`).join('');({home,practice,wrong,cards,exam,casesPage,guide}[page==='cases'?'casesPage':page])()}
function home(){let done=new Set(state.history.map(h=>h.id)),right=state.history.filter(h=>h.ok).length,wr=Object.values(state.wrong).filter(w=>!w.mastered).length;let next=modules.findIndex((m,i)=>facts.some((f,j)=>f[0]===i&&!state.learned.includes(j)));if(next<0)next=0;
$('#app').innerHTML=heading('把每一次练习，变成进步。','从零开始，也能有条不紊。今天先理解一个要点，再练一组题。')+`<section class="hero"><div><span class="eyebrow" style="color:#c9dba8">你的三级备考，从这里开始</span><h2>先学懂重点，<br>再把分数练扎实。</h2><p>六个学习模块 · ${questions.length} 道原创练习 · 5 个实操案例</p><button class="primary" onclick="filterModule='${next}';go('cards')">${state.learned.length?'继续学习':'开始第一课'}　→</button> <button onclick="startPractice('all',10)">每日 10 题</button></div><div class="orbit"><b>L3</b><span>LEARN · PRACTICE</span></div></section><div class="stats"><div class="card stat"><small>已练习题目</small><strong>${done.size}<small> / ${questions.length}</small></strong><span class="muted">累计 ${state.history.length} 次作答</span></div><div class="card stat"><small>练习正确率</small><strong>${pct(right,state.history.length)}<small> %</small></strong><span class="muted">按全部已提交作答统计</span></div><div class="card stat"><small>待巩固错题</small><strong>${wr}<small> 题</small></strong><a href="#wrong" class="muted">回顾薄弱点 →</a></div><div class="card stat"><small>累计学习</small><strong>${state.days.length}<small> 天</small></strong><span class="muted">行动比焦虑更有用</span></div></div><div class="grid"><section class="card"><div class="row"><h2>你的学习路线</h2><span class="pill">循序渐进</span></div>${modules.map((m,i)=>{let fs=facts.map((f,j)=>f[0]===i?j:null).filter(x=>x!==null),n=fs.filter(j=>state.learned.includes(j)).length;return `<div class="module"><div class="row"><div class="flex"><span class="number">0${i+1}</span><div><h3>${m[0]}</h3><span class="muted">${m[1]} · ${n}/${fs.length} 要点</span></div></div><button onclick="filterModule='${i}';go('cards')">学习 →</button></div><div class="progress"><div style="width:${pct(n,fs.length)}%"></div></div></div>`}).join('')}</section><div><section class="card"><span class="eyebrow">TODAY'S FOCUS</span><h2>今日学习清单</h2><p class="muted">建议 30–45 分钟，先理解后做题。</p><p>① 学习 3 张速记卡</p><p>② 完成 10 道随机练习</p><p>③ 复习待巩固错题</p><p>④ 写一个实操案例的思路</p><button class="primary" onclick="go('cases')">进入实操训练 ↗</button></section><section class="card" style="margin-top:20px"><h3>备考日历</h3><label class="muted" for="target">设置你的考试日期</label><input id="target" type="date" value="${esc(state.date)}" onchange="state.date=this.value;save();home()" style="width:100%;margin:10px 0"><p class="muted">${state.date?countdown():'未设置日期也可以立即开始学习。'}</p><a href="#guide">查看 14 天学习安排 →</a></section></div></div>`}
function countdown(){let n=Math.ceil((new Date(state.date+'T00:00:00')-new Date(today()+'T00:00:00'))/86400000);return n>=0?`距离目标考试还有 ${n} 天`:'目标日期已到，继续巩固或更新日期。'}
function moduleSelect(){return `<select aria-label="筛选模块" onchange="filterModule=this.value;render()"><option value="all">全部模块</option>${modules.map((m,i)=>`<option value="${i}" ${filterModule==i?'selected':''}>${m[0]}</option>`).join('')}</select>`}
function pool(){return questions.filter(q=>(filterModule==='all'||q.m==filterModule)&&(filterType==='all'||q.type===filterType)&&(!filterText||`${q.stem} ${q.explain}`.includes(filterText)))}
function practice(){if(session&&!session.exam){drawQuestion();return}$('#app').innerHTML=heading('题目练习','先分章理解，再混合练习。每次提交都有解析，答错自动进入错题库。')+`<div class="toolbar">${moduleSelect()}<select aria-label="题型" onchange="filterType=this.value;render()">${['all','单选','多选','判断'].map(t=>`<option value="${t}" ${filterType===t?'selected':''}>${t==='all'?'全部题型':t}</option>`).join('')}</select><input type="search" placeholder="搜索知识点，如：召回率" value="${esc(filterText)}" oninput="filterText=this.value;document.getElementById('qcount').textContent=pool().length"><button class="primary" onclick="startFiltered()">开始练习 →</button></div><p class="muted">当前范围 <b id="qcount">${pool().length}</b> 题 · 多选题须全部选对，不设部分分</p><div class="cards">${modules.map((m,i)=>`<section class="card"><span class="pill">${m[2]}</span><h2 style="margin-top:15px">${m[0]}</h2><p class="muted">${m[1]}</p><div class="row"><span class="muted">${questions.filter(q=>q.m===i).length} 道题</span><button onclick="startPractice('${i}',999)">分章练习 →</button></div></section>`).join('')}</div><div class="actions"><button onclick="startList(state.stars,'收藏练习')">练习收藏题（${state.stars.length}）</button><button onclick="startList(questions.filter(q=>!state.history.some(h=>h.id===q.id)).map(q=>q.id),'未做题练习')">只练未做题</button></div>`}
function startFiltered(){startList(shuffled(pool()).map(q=>q.id),'筛选练习')}
function startPractice(m,n){startList(shuffled(questions.filter(q=>m==='all'||q.m==m)).slice(0,n).map(q=>q.id),'专项练习')}
function startList(ids,title){if(!ids.length){toast('当前没有符合条件的题目');return}session={ids,title,answers:{},exam:false};pos=0;selection=[];revealed=false;result=null;location.hash='practice';page='practice';render()}
function drawQuestion(){let q=qby(session.ids[pos]),record=session.answers[q.id];selection=record?[...record]:selection;let examMode=session.exam;let submitted=!examMode&&revealed;let ok=eq(selection,q.answer);$('#app').innerHTML=heading(examMode?'模拟考试进行中':session.title,examMode?'答案自动暂存；切换页面或刷新不会停止计时。交卷后查看解析。':'认真理解每个选项，比记住答案字母更重要。')+`<div class="row"><span class="pill">${modules[q.m][0]} · ${q.type}</span><span>${examMode?'<b id="timer"></b>　':''}${pos+1} / ${session.ids.length}</span></div><div class="progress"><div style="width:${(pos+1)/session.ids.length*100}%"></div></div><section class="card" style="margin-top:22px"><div class="row"><span class="muted">${q.id.toUpperCase()} · 原创学习题</span>${examMode?'':`<button onclick="star('${q.id}')">${state.stars.includes(q.id)?'★ 已收藏':'☆ 收藏'}</button>`}</div><h2 class="question">${esc(q.stem)}</h2>${q.type==='多选'?'<p class="muted">请选择所有符合条件的选项。</p>':''}<div class="options">${q.options.map((o,i)=>`<button class="option ${selection.includes(i)?'selected':''} ${submitted&&q.answer.includes(i)?'correct':''} ${submitted&&selection.includes(i)&&!q.answer.includes(i)?'wrong':''}" onclick="choose(${i})" ${submitted?'disabled':''}><b>${'ABCD'[i]}</b>${esc(o)}</button>`).join('')}</div>${submitted?`<div class="explain ${ok?'':'error'}"><b>${ok?'回答正确，继续保持':'这里值得再复习一次'}</b><p>正确答案：${q.answer.map(i=>'ABCD'[i]).join('、')}</p>${esc(q.explain)}</div><label class="muted">我的笔记</label><textarea placeholder="用自己的话记住为什么……" oninput="state.notes['${q.id}']=this.value;save()">${esc(state.notes[q.id]||'')}</textarea>`:''}<div class="actions">${examMode?`<button onclick="move(-1)" ${pos===0?'disabled':''}>上一题</button><button class="primary" onclick="move(1)" ${pos===session.ids.length-1?'disabled':''}>下一题</button><button onclick="finishExam(false)">交卷</button>`:`${!submitted?'<button class="primary" onclick="submitPractice()">提交答案</button>':`<button class="primary" onclick="nextPractice()">${pos===session.ids.length-1?'查看练习结果':'下一题 →'}</button>`}<button onclick="session=null;practice()">结束本组</button>`}</div></section>${examMode?`<section class="card" style="margin-top:20px"><h3>答题卡 <small class="muted">浅绿表示已作答</small></h3><div class="answer-grid">${session.ids.map((id,i)=>`<button class="${session.answers[id]?.length?'done':''} ${i===pos?'current':''}" onclick="jump(${i})">${i+1}</button>`).join('')}</div></section>`:''}`;if(examMode)tick()}
function choose(i){if(revealed&&!session.exam)return;let q=qby(session.ids[pos]);selection=q.type==='多选'?(selection.includes(i)?selection.filter(x=>x!==i):[...selection,i]):[i];if(session.exam){session.answers[q.id]=selection;state.activeExam=session;save()}drawQuestion()}
function recordAnswer(q,ans,mode){let ok=eq(ans,q.answer);state.history.push({id:q.id,ok,at:Date.now(),mode});if(!ok){let old=state.wrong[q.id]||{count:0};state.wrong[q.id]={...old,count:old.count+1,mastered:false,last:Date.now(),answer:ans}}else if(state.wrong[q.id]){state.wrong[q.id].mastered=true}activity();return ok}
function submitPractice(){if(!selection.length){toast('请先选择答案');return}let q=qby(session.ids[pos]);session.answers[q.id]=[...selection];recordAnswer(q,selection,'practice');save();revealed=true;drawQuestion()}
function nextPractice(){if(pos<session.ids.length-1){pos++;selection=[];revealed=false;drawQuestion()}else{let correct=session.ids.filter(id=>eq(session.answers[id]||[],qby(id).answer)).length;$('#app').innerHTML=heading('这一组，练完了。','复盘错误原因，再进入下一组。')+`<section class="card empty"><div class="score">${pct(correct,session.ids.length)}<small>%</small></div><p>答对 ${correct} / ${session.ids.length} 题；错题已自动整理。</p><button class="primary" onclick="session=null;go('wrong')">复习错题 →</button> <button onclick="session=null;practice()">返回练习</button></section>`;session=null}}
function star(id){state.stars=state.stars.includes(id)?state.stars.filter(x=>x!==id):[...state.stars,id];save();drawQuestion()}
function wrong(){let ids=Object.keys(state.wrong).filter(id=>qby(id)&&(filterModule==='all'||qby(id).m==filterModule)),pending=ids.filter(id=>!state.wrong[id].mastered);$('#app').innerHTML=heading('把错题，变成拿手题。','答错自动收录；再次答对会标记已掌握。已掌握题仍保留，便于回看。')+`<div class="toolbar">${moduleSelect()}<button class="primary" onclick="startList(${JSON.stringify(pending).replace(/"/g,'&quot;')},'错题重练')">重练待巩固（${pending.length}）</button><button onclick="startList(${JSON.stringify(ids).replace(/"/g,'&quot;')},'全部错题回顾')">重练全部</button></div>${!ids.length?'<section class="card empty"><h2>这里暂时没有错题</h2><p class="muted">开始练习后，答错的题会自动来到这里。</p><button class="primary" onclick="go(\'practice\')">去练习</button></section>':ids.sort((a,b)=>state.wrong[b].count-state.wrong[a].count).map(id=>{let q=qby(id),w=state.wrong[id];return `<section class="card" style="margin-bottom:14px"><div class="row"><span class="pill">${w.mastered?'已掌握':'待巩固'} · 累计错 ${w.count} 次</span><span class="muted">${modules[q.m][0]}</span></div><h3 style="margin-top:15px">${esc(q.stem)}</h3><details><summary>查看正确答案与解析</summary><p>${q.answer.map(i=>`${'ABCD'[i]}．${esc(q.options[i])}`).join('<br>')}</p><p class="muted">${esc(q.explain)}</p>${state.notes[id]?`<p class="note">我的笔记：${esc(state.notes[id])}</p>`:''}</details><div class="actions"><button onclick="startList(['${id}'],'单题巩固')">再练一次</button><button onclick="state.wrong['${id}'].mastered=!state.wrong['${id}'].mastered;save();wrong()">${w.mastered?'重新加入待巩固':'标记已掌握'}</button></div></section>`}).join('')}`}
function cards(){let ids=facts.map((f,i)=>i).filter(i=>filterModule==='all'||facts[i][0]==filterModule);cardIndex=Math.min(cardIndex,ids.length-1);let id=ids[cardIndex],f=facts[id];$('#app').innerHTML=heading('要点速记，先懂再记。','先尝试用自己的话回答，再翻面看解释。掌握后可直接练对应题。')+`<div class="toolbar">${moduleSelect()}<span class="muted">已掌握 ${state.learned.length} / ${facts.length} 个要点</span></div><section class="card" style="min-height:310px;padding:35px"><div class="row"><span class="pill">${modules[f[0]][0]}</span><span class="muted">${cardIndex+1} / ${ids.length}</span></div><h2 style="font-size:30px;margin-top:30px">${f[1]}</h2>${flipped?`<p style="font-size:19px">${f[2]}</p><p class="note">举个例子：${f[4]}</p><p><b>一句话记忆：</b>${f[5]}</p>`:'<p class="muted">它是什么意思？遇到实际任务时，你会怎么做？</p><p class="eyebrow">先想一想 · 再揭晓</p>'}<div class="actions"><button class="primary" onclick="flipped=!flipped;cards()">${flipped?'收起解释':'翻卡查看解释 ↻'}</button><button onclick="toggleLearned(${id})">${state.learned.includes(id)?'✓ 已掌握，重新学习':'标记已掌握'}</button><button onclick="startList(['q${id+1}'],'要点练习')">练一道对应题 →</button></div></section><div class="row" style="margin-top:18px"><button onclick="cardIndex--;flipped=false;cards()" ${cardIndex===0?'disabled':''}>← 上一个</button><button onclick="cardIndex++;flipped=false;cards()" ${cardIndex===ids.length-1?'disabled':''}>下一个 →</button></div><section class="card" style="margin-top:24px"><h2>要点目录</h2><div class="tabs">${ids.map((j,i)=>`<button class="${i===cardIndex?'active':''}" onclick="cardIndex=${i};flipped=false;cards();window.scrollTo(0,0)">${state.learned.includes(j)?'✓ ':''}${facts[j][1]}</button>`).join('')}</div></section>`}
function toggleLearned(id){state.learned=state.learned.includes(id)?state.learned.filter(x=>x!==id):[...state.learned,id];activity();save();cards()}
function exam(){if(state.activeExam){session=state.activeExam;pos=Math.min(session.pos||0,session.ids.length-1);selection=session.answers[session.ids[pos]]||[];drawQuestion();return}if(result){showExamResult(result);return}$('#app').innerHTML=heading('模拟考试，检验真实掌握。','闭卷计时，交卷后统一评分。练习卷为本站自定义，不代表当地正式考试题型和配比。')+`<div class="cards"><section class="card"><span class="pill">轻量自测</span><h2 style="margin-top:20px">20 分钟 · 快速检测</h2><p class="muted">从六个模块抽取 20 题，适合完成一轮学习后检验薄弱点。</p><button class="primary" onclick="startExam(20,20)">开始自测 →</button></section><section class="card"><span class="pill">综合训练</span><h2 style="margin-top:20px">90 分钟 · 综合模拟</h2><p class="muted">随机抽取 60 题。百分制等权计分，60 分为本站练习参考线。</p><button class="primary" onclick="startExam(60,90)">开始综合模拟 →</button></section></div><section class="card" style="margin-top:25px"><h2>考试记录</h2>${state.exams.length?`<table><thead><tr><th>时间</th><th>题量</th><th>成绩</th><th>复盘</th></tr></thead><tbody>${state.exams.slice().reverse().map(e=>`<tr><td>${new Date(e.at).toLocaleString('zh-CN')}</td><td>${e.ids.length}</td><td>${e.score} 分</td><td><button onclick="result=state.exams.find(x=>x.at===${e.at});showExamResult(result)">查看</button></td></tr>`).join('')}</tbody></table>`:'<p class="muted">还没有考试记录。第一次成绩是起点，后续复盘才是提升的关键。</p>'}</section><p class="note" style="margin-top:20px">理论模拟不能替代技能考核准备。建议同时完成“实操训练”，并核对评价机构要求的具体软件、题型和操作流程。</p>`}
function startExam(n,min){let ids=[];modules.forEach((_,m)=>ids.push(...shuffled(questions.filter(q=>q.m===m)).slice(0,Math.floor(n/6)).map(q=>q.id)));ids.push(...shuffled(questions.filter(q=>!ids.includes(q.id))).slice(0,n-ids.length).map(q=>q.id));session={exam:true,ids:shuffled(ids),answers:{},end:Date.now()+min*60000,started:Date.now(),pos:0};state.activeExam=session;save();pos=0;selection=[];revealed=false;exam()}
function jump(i){pos=i;session.pos=i;selection=session.answers[session.ids[i]]||[];state.activeExam=session;save();drawQuestion()}
function move(d){jump(Math.max(0,Math.min(session.ids.length-1,pos+d)))}
function tick(){let active=state.activeExam;if(!active)return;let secs=Math.max(0,Math.ceil((active.end-Date.now())/1000));if($('#timer'))$('#timer').textContent=`剩余 ${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')}`;if(!secs)finishExam(true)}
setInterval(tick,1000);
function finishExam(auto){let s=state.activeExam;if(!s)return;let unanswered=s.ids.filter(id=>!s.answers[id]?.length).length;if(!auto&&!confirm(`确认交卷？${unanswered?'还有 '+unanswered+' 题未作答，将按错误计分。':'交卷后不能修改答案。'}`))return;let right=0;s.ids.forEach(id=>{if(recordAnswer(qby(id),s.answers[id]||[],'exam'))right++});result={...s,at:Date.now(),score:Math.round(right/s.ids.length*10000)/100,right,auto};state.exams.push(result);state.activeExam=null;session=null;save();go('exam');showExamResult(result)}
function showExamResult(e){$('#app').innerHTML=heading('考试复盘','分数告诉你现在的位置，错因告诉你下一步怎么走。')+`<section class="card"><div class="row"><div><div class="score">${e.score}<small style="font-size:18px"> / 100</small></div><p>${e.score>=60?'达到本站练习参考线，继续加强实操。':'还需巩固，建议先学习错误集中的模块。'}<br><span class="muted">答对 ${e.right}/${e.ids.length} · ${e.auto?'到时自动交卷':'手动交卷'}</span></p></div><button onclick="result=null;exam()">返回考试中心</button></div><div class="stats">${modules.map((m,i)=>{let ids=e.ids.filter(id=>qby(id).m===i);return `<div><span class="muted">${m[0]}</span><h3>${ids.filter(id=>eq(e.answers[id]||[],qby(id).answer)).length} / ${ids.length}</h3></div>`}).join('')}</div></section><section class="card" style="margin-top:24px"><h2>逐题解析</h2>${e.ids.map((id,i)=>{let q=qby(id),ans=e.answers[id]||[],ok=eq(ans,q.answer);return `<details><summary>${ok?'✓':'○'} ${i+1}. ${esc(q.stem)}</summary><p class="muted">${q.options.map((o,j)=>`${'ABCD'[j]}．${esc(o)}`).join('<br>')}</p><p>你的答案：${ans.length?ans.map(j=>'ABCD'[j]).join('、'):'未作答'}　正确答案：${q.answer.map(j=>'ABCD'[j]).join('、')}</p><p class="note">${esc(q.explain)}</p></details>`}).join('')}</section>`}
function casesPage(){ $('#app').innerHTML=heading('实操训练，把知识用起来。','5 个典型任务 · 写下方案 · 对照步骤自查。自评用于学习反馈，不等于正式技能考试评分。')+cases.map((c,i)=>`<section class="card" style="margin-bottom:20px"><span class="pill">案例 0${i+1} · ${modules[c.m][0]}</span><h2 style="margin-top:16px">${c.title}</h2><p>${c.brief}</p><label class="muted" for="case${i}">我的作答（自动保存）</label><textarea id="case${i}" placeholder="按目标、步骤、质量检查、结果验证来写……" oninput="state.caseAnswers[${i}]=this.value;activity();save()">${esc(state.caseAnswers[i]||'')}</textarea><details><summary>查看参考思路与自查清单</summary><p class="note">${c.answer}</p>${c.steps.map((s,j)=>`<label style="display:block;margin:10px 0"><input type="checkbox" ${(state.caseChecks[i]||[]).includes(j)?'checked':''} onchange="caseCheck(${i},${j},this.checked)"> ${s}</label>`).join('')}<p class="muted">请只勾选你的作答确实覆盖的项目；未覆盖项就是下一次改进目标。</p></details></section>`).join('')}
function caseCheck(i,j,on){let a=state.caseChecks[i]||[];state.caseChecks[i]=on?[...new Set([...a,j])]:a.filter(x=>x!==j);activity();save()}
function guide(){let schedule=['认识职业与AI概念','分类回归与数据基础','需求澄清与流程图','业务拆解与验收指标','数据清洗与质量检查','标注规则与一致性','复习前六天错题','训练验证测试划分','指标计算与错误分析','监控优化与灰度回滚','培训指导与实操案例','综合模拟与复盘','重练薄弱模块','速记回顾与考前核对'];$('#app').innerHTML=heading('零基础备考指南','先建立框架，再反复练习。学习安排可以按自己的时间拉长，不必机械追赶。')+`<section class="card"><h2>14 天学习路线</h2><p class="muted">每天建议 30–60 分钟用于本项目；实际学习时长取决于基础与当地考核要求。点击一天可标记完成。</p><div class="steps">${schedule.map((s,i)=>`<button class="step ${state.plan.includes(i)?'done':''}" onclick="state.plan=state.plan.includes(${i})?state.plan.filter(x=>x!==${i}):[...state.plan,${i}];activity();save();guide()"><b>${state.plan.includes(i)?'✓':String(i+1).padStart(2,'0')}</b>${s}</button>`).join('')}</div></section><div class="cards" style="margin-top:22px"><section class="card"><h2>先学什么？</h2><p>① 用“职业基础”理解特征、标签和任务类型。</p><p>② 以业务流程、数据规范、测试评估、产品优化为主线学习。</p><p>③ 每个要点先用自己的话解释，再练题验证。</p><p>④ 能答对之后，还要能写出实操方案并解释原因。</p></section><section class="card"><h2>怎么用错题库？</h2><p>答错 → 阅读解析 → 写一句自己的错因 → 隔天重练。</p><p>再次答对会标记“已掌握”，但历史错题保留，可再次练习。</p><p>如果靠记字母答对，建议重新加入待巩固，重点解释每个错误选项。</p></section></div><section class="card" style="margin-top:22px"><h2>考试范围与资料来源</h2><p>本项目参考《人工智能训练师国家职业技能标准（2021年版）》的职业能力框架，结合通用数据与测试知识编写原创学习内容。三级对应高级工，学习应兼顾理论理解与技能操作。</p><p>题库不是官方题库，不声称覆盖当地全部考点。20分钟与90分钟练习卷、抽题数量及等权评分均为本站训练设计。</p><p>报考前请向评价机构核对：最新适用标准、报名条件、考试日期、理论题型、技能软件与操作要求、合格规则。本文不提供报名资格判定。</p><p><a href="https://www.osta.org.cn/api/sys/downloadFile/decrypt?fileName=4eNsZIOv3WFNDfbnldJHeA%2F2024%2F4%2F29%2F6761815658ea468cbc0caa8974357703.pdf" target="_blank" rel="noopener">技能人才评价工作网：国家职业技能标准（2021年版） ↗</a></p><p><a href="https://www.mohrss.gov.cn/wap/zc/zqyj/202106/W020210617509883457681.pdf" target="_blank" rel="noopener">人力资源社会保障部：标准相关公开资料 ↗</a></p><p class="muted">内容核对日期：2026-10-26。页面中的标准参考用于能力框架定位；实际认定安排以评价机构当期公告为准。</p></section><section class="card" style="margin-top:22px"><h2>学习数据与备份</h2><p>进度、错题、笔记、实操作答和考试记录保存在当前设备的浏览器中，不自动跨设备同步。更换浏览器或清除浏览器数据前，请导出备份。</p><button onclick="backup()">导出完整学习备份</button> <label class="import">导入备份<input type="file" accept="application/json" onchange="restore(event)"></label></section>`}
function backup(){let b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`训练师学习备份-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出学习备份')}
function validBackup(d){if(!d||d.version!==1||!Array.isArray(d.history)||!Array.isArray(d.stars)||!Array.isArray(d.learned)||!Array.isArray(d.days)||!Array.isArray(d.exams)||!Array.isArray(d.plan))return false;if(!['wrong','notes','caseAnswers','caseChecks'].every(k=>d[k]&&typeof d[k]==='object'&&!Array.isArray(d[k])))return false;if(!d.history.every(h=>qby(h.id)&&typeof h.ok==='boolean')||!d.stars.every(qby)||!d.learned.every(i=>Number.isInteger(i)&&i>=0&&i<facts.length))return false;const validExam=e=>e&&Array.isArray(e.ids)&&e.ids.length>0&&e.ids.every(qby)&&e.answers&&typeof e.answers==='object'&&e.ids.every(id=>!e.answers[id]||(Array.isArray(e.answers[id])&&e.answers[id].every(i=>Number.isInteger(i)&&i>=0&&i<qby(id).options.length)));return d.exams.every(e=>validExam(e)&&Number.isFinite(e.score)&&Number.isFinite(e.at))&&(!d.activeExam||(validExam(d.activeExam)&&Number.isFinite(d.activeExam.end)&&d.activeExam.exam===true))&&Object.entries(d.wrong).every(([id,w])=>qby(id)&&w&&Number.isFinite(w.count))&&Object.values(d.notes).every(v=>typeof v==='string')&&Object.values(d.caseAnswers).every(v=>typeof v==='string')&&Object.values(d.caseChecks).every(Array.isArray)&&d.days.every(x=>typeof x==='string')&&typeof d.date==='string'}
async function restore(ev){let f=ev.target.files[0];if(!f)return;try{if(f.size>10e6)throw Error();let d=JSON.parse(await f.text());if(!validBackup(d))throw Error();if(!confirm('导入将替换当前浏览器的学习记录。建议先导出当前备份。确认继续？'))return;state={...fresh(),...d};session=null;result=null;save();render();toast('学习记录已恢复')}catch{toast('无法导入：请选择本项目导出的有效 JSON 备份')}finally{ev.target.value=''}}
window.legacyV1={home,guide,casesPage,cards};

